# x_g6 — expansion group 6: walls, construction and building-regulation classes.
# New knowledge points: building classes and fire resistance of load-bearing walls; cellar walls and
# slabs; separating walls between units; combustibility of external walls/claddings; cavity walls;
# single-leaf external walls; insulation of concrete external walls; perimeter ties; load-bearing vs
# non-load-bearing walls; fire-retarding (F 30) corridor walls.
# All items are supplements (pairing='supplement').

# ---------------------------------------------------------------- building classes and fire resistance
C['g6_lb_class'] = cite('page_0526', 'Load-bearing and bracing walls and columns must be constructed fireproof in buildings of class 5, highly fire-retarding in buildings of class 4 and fire-retarding in buildings of classes 1 and 2')
C['g6_class35'] = cite('page_0476', 'buildings with more than two flats or a usable area of 400 m² (building classes 3–5)')
C['g6_cellar_walls'] = cite('page_0526', 'In cellars, they have to be constructed fireproof and, in buildings of classes 1 and 2, fire-retarding.')
C['g6_cellar_slab'] = cite('page_0527', 'Ceilings must be fireproof, or at least fire-retarding, and slabs over cellars must be fireproof.')
C['g6_solid_slab'] = cite('page_0527', 'Solid slabs (e.g. reinforced concrete slabs → ①, hollow pot floors) have sufficient fire resistance under certain conditions without additional protection measures.')
C['g6_sep_wall'] = cite('page_0526', 'The fire resistance duration of separating walls between residential or commercial units (or units and rooms used otherwise) must correspond to the quality of the load-bearing components of the storey. These must extend to the structural slab (in roof spaces up to the roof cladding).')
C['g6_ext_noncomb'] = cite('page_0526', 'Non-load-bearing external walls and non-load-bearing parts of load-bearing external walls are (except for buildings of building classes 1–3) to be constructed of non-combustible (at least fire-retarding) materials.')
C['g6_cladding_gen'] = cite('page_0526', 'External wall claddings, including insulation and support construction, have to be made of flame-resistant materials.')
C['g6_lb_except'] = cite('page_0526', 'This does not apply to the uppermost storeys of roof spaces without occupied rooms above them and balconies.')
C['g6_slab_except'] = cite('page_0527', 'Exceptions apply for buildings of classes 1 and 2, slabs and ceilings above roof spaces, and balconies, slabs and ceilings within residential dwellings.')
C['g6_cladding12'] = cite('page_0526', 'For buildings of classes 1 and 2, external wall claddings of normally flammable materials are permissible, if the spread of fire to neighbouring buildings is effectively prevented.')
C['g6_corridor_f30'] = cite('page_0528', 'A typical area of application for G-glazing is the openings for lighting installed in corridor walls, which have to be constructed fire-retarding (F 30) as the side walls of escape routes. The lower edge of the glass must in this case be at least 1.80 m above floor level, so that in case of fire the corridor remains usable in the radiation shadow.')
C['g6_stud'] = cite('page_0526', 'Non-load-bearing separating walls can be constructed as stud partitions of various qualities')

# ---------------------------------------------------------------- wall construction
C['g6_cavity'] = cite('page_0087', 'Cavity walls consist of an inner load-bearing wall and an outer non-load-bearing weather protection facing (minimum thickness 90 mm).')
C['g6_air_gap'] = cite('page_0087', 'The width of the air gap should be min. 40 mm (max. 150 mm).')
C['g6_single_leaf'] = cite('page_0087', 'are unproblematic regarding building physics, but on account of the high thermal insulation requirements can only be built with materials with high thermal insulation value (e.g. aerated blocks) and special thermally insulated mortars and plasters.')
C['g6_concrete_ext'] = cite('page_0090', 'Solid concrete walls can be used as external walls only with an additional thermal insulation layer.')
C['g6_tie'] = cite('page_0089', 'Perimeter ties are required for the transfer of horizontal forces over all external and transverse walls in buildings with more than two full storeys or more than 18 m length and walls with many or large openings under the floor slab.')
C['g6_tie_rc'] = cite('page_0089', 'These are normally made of reinforced concrete and constructed together with columns and massive floor slabs.')
C['g6_lb_def'] = cite('page_0089', 'Walls which have to bear more than their self-weight on one storey are called load-bearing walls.')
C['g6_nlb_def'] = cite('page_0089', 'Walls which are only loaded by their self-weight and are not used for bracing against buckling are called non-load-bearing.')

ITEMS += [
    # ============================================================ cavity walls
    dict(project='fantasy_residential_building_1', derived_from=[], pairing='supplement', question_type='compliance',
         question='Each upper floor of this building holds two flats, one in the west wing and one in the east wing. The only room-to-room contact between them is at the north end, where Utility room 27 (west) and Utility room 35 (east) on the First Floor share a single wall. Identify that wall. Given the building\'s regulatory class, what fire performance must it have, and does its geometry meet the requirement?',
         answer='The shared wall is "STB 15.0 - Sichtbeton" (0RgKgXPa5AqeGvHba2KWCC), 150 mm of exposed reinforced concrete, at x −3.09 to −2.94 m. The building has 6 flats (2 per floor) and about 1401 m² of spaces, so by the book\'s gloss for building classes 3–5 ("more than two flats or a usable area of 400 m²", given in brackets in its rubbish-storage rule) it is in class 3–5. A wall between two residential units must have the fire resistance of the storey\'s load-bearing components. Here those are reinforced concrete: STB 30.0 outer walls, STB 15.0 load-bearing cross walls and an STB 20.0 slab. A 150 mm solid concrete wall is non-combustible and as massive as the load-bearing 150 mm walls. Assuming the same concrete class and cover as those walls, it reaches the same fire resistance even though it is flagged LoadBearing = False. It also has to run up to the structural slab. It goes from 3.40 m to 6.60 m, which is exactly the underside of the 200 mm Second Floor slab (6.60–6.80 m). So it complies.',
         evidence=['IfcSpace 27 Utility room (x −7.01…−3.09, y 8.05…10.45 m) and 35 Utility room (x −2.94…0.99 m), First Floor.',
                   'IfcWall 0RgKgXPa5AqeGvHba2KWCC "Basiswand:STB 15.0 - Sichtbeton", x −3.09…−2.94, y 8.05…10.45, z 3.40…6.60 m, material StB - Sichtbeton, LoadBearing = False.',
                   'IfcSlab 1cPCOuJxHAURgGeW1MlSZo "Geschossdecke:STB 20.0", z 6.60…6.80 m; load-bearing walls STB 30.0 (24, external) and STB 15.0 (24 with LoadBearing = True).',
                   'Space totals: Ground 372.1, First 487.1, Second 541.9 m² (1401.1 m²); 2 flats per upper floor and on the ground floor (6 in total, original QA).'],
         hidden_knowledge='Book\'s gloss (rubbish-storage rule): more than two flats or 400 m² usable area = building classes 3–5; separating walls between units must have the fire resistance of the storey\'s load-bearing components and extend to the structural slab.',
         basis=[C['g6_class35'], C['g6_sep_wall']],
         rubric=['Identifies the STB 15.0 wall between utility rooms 27 and 35', 'Classifies the building as class 3–5 (6 flats) via the book\'s gloss', 'Requires the wall to match the load-bearing RC components; 150 mm RC qualifies (assumption stated)', 'Checks the wall reaches the slab underside (6.60 m)']),
    dict(project='samuel_macalister_sample_house', derived_from=[], pairing='supplement', question_type='compliance',
         question='This single-family house combines cast concrete walls ("CL_W1", "Retaining - 300mm Concrete") with timber construction: structural timber insulated panels finished with timber cladding ("Wall - Timber Clad"), timber-stud partitions and a concrete-clad SIP wall. If it were built under the German model building regulations, would its fire-protection class allow this timber construction and the timber façade cladding? Explain.',
         answer='Yes. The house is one dwelling with about 279 m² of rooms (Level 1 177.2 m², Level 2 101.7 m²). That is fewer than three flats and less than 400 m², so by the book\'s gloss for classes 3–5 ("more than two flats or a usable area of 400 m²", a bracket in its rubbish-storage rule) it falls below class 3, i.e. class 1–2. In classes 1–2, load-bearing and bracing walls only need to be fire-retarding, a level timber-panel and timber-stud walls can reach. Non-load-bearing external walls need not be non-combustible in classes 1–3. External wall claddings, including insulation and support construction, must in general be flame-resistant, which untreated timber cladding is not; but classes 1 and 2 are the exception: there cladding of normally flammable material, here the 22 mm timber cladding over the SIP walls, is permissible as long as the spread of fire to neighbouring buildings is effectively prevented. The model gives no plot boundaries, so that condition (distance or a non-combustible wall towards a neighbour) has to be checked on the site plan. The solid concrete walls are well above the requirement anyway.',
         evidence=['IfcWall "Basic Wall:Wall - Timber Clad" (e.g. 2OulbipBrAkwQNv_KJRV9c), 7 instances: Timber Cladding 22 | Wood Stud 25 | OSB 15 | SIP insulation 112 | OSB 15 | Plasterboard 13 mm (202 mm).',
                   '"Basic Wall:SIP 202mm Wall - conc clad" (4), "Interior - Partition" (wood stud 100 mm, 15), "Interior - 165 Partition (1-hr)" (3); concrete "CL_W1" 280 mm and "Retaining - 300mm Concrete" walls.',
                   'Storeys Level 1 0.00 m, Level 2 3.00 m, Roof Line 6.00 m; one kitchen, one living room: a single dwelling.',
                   'Original QA areas (IfcSpace areas are empty in the IFC): Level 1 177.2 m², Level 2 101.7 m².'],
         hidden_knowledge='Book\'s gloss (rubbish-storage rule): more than two flats or 400 m² usable area = classes 3–5; classes 1–2 need only fire-retarding load-bearing walls; non-combustible non-load-bearing external walls only from class 4; external wall claddings must generally be flame-resistant, with normally flammable claddings permissible as an exception in classes 1–2 if spread to neighbours is effectively prevented.',
         basis=[C['g6_class35'], C['g6_lb_class'], C['g6_ext_noncomb'], C['g6_cladding_gen'], C['g6_cladding12']],
         rubric=['Classifies as class 1–2 via the book\'s > 2 flats / 400 m² gloss (1 dwelling, ≈279 m² < 400 m²)', 'Load-bearing walls need only be fire-retarding → timber construction possible', 'Claddings must generally be flame-resistant; timber cladding permitted only as the class 1–2 exception, if fire spread to neighbours is prevented', 'Notes the site/boundary condition cannot be checked from the model']),

    # ============================================================ cellars
    dict(project='ac20', derived_from=[], pairing='supplement', question_type='compliance',
         question='This office building has a full basement ("Keller", −3.00 m) under four storeys. The basement walls are 300 mm and 200 mm Kalksandstein (calcium-silicate) masonry, and the ground-floor slab above it is 300 mm "Stahlbeton". Determine the building\'s class from the model. What fire performance does that class require of the basement walls and of the slab over the basement, and are the chosen constructions appropriate?',
         answer='The spaces add up to 1939.4 m², about 430 m² per storey, so it is clearly over the 400 m² usable area that the book (in a bracket in its rubbish-storage rule) equates with building classes 3–5; on that gloss it is in class 3–5. In cellars, load-bearing and bracing walls and columns must then be fireproof (the class 1–2 relief to fire-retarding does not apply), and the slab over the cellar must be fireproof; the book\'s exceptions to the slab rule (classes 1 and 2, ceilings above roof spaces, slabs within dwellings) do not cover a class 3–5 office basement. The basement walls are solid calcium-silicate masonry, 300 mm outside and 200 mm inside, plastered on both faces. They are non-combustible, massive walls, the kind normally classified fireproof, though the model carries no fire rating, so this is an assumption. The 300 mm solid reinforced-concrete slab over the basement (Decke-001 at −0.30…0.00 m) is a solid slab. Neufert says such slabs have enough fire resistance without additional protection under certain conditions (mainly concrete cover). So both constructions are appropriate. The rating still has to be shown, and the model\'s Pset_WallCommon has no FireRating.',
         evidence=['Storeys Keller −3.0, Erdgeschoss 0.0, 1. OG 3.0, 2. OG 6.0, Dachgeschoss 9.0 m.',
                   'IfcSpace areas: Keller 438.1, EG 442.1, 1. OG 428.4, 2. OG 428.4, DG 202.4 m² (1939.4 m²).',
                   'Keller walls: "Kalksandstein 2816491304 300" (external, e.g. 2UZhzWc8v0fA0sfv__WgLn, z −3.00…−0.30 m), "Kalksandstein 2816491304 200" (11 internal), "Kalksandstein 2774059904 300" (2); ArchiCAD surfaces "Verputz, weiß" both sides; no FireRating.',
                   'IfcSlab 3QoJ6BxnbEJAsAxl5gQcR_ "Decke-001", "Stahlbeton 2747937872 300", Erdgeschoss, z −0.30…0.00 m, 42.0 × 17.5 m.'],
         hidden_knowledge='Book\'s gloss (rubbish-storage rule): more than two flats or 400 m² usable area = classes 3–5; in cellars load-bearing and bracing walls and columns must be fireproof (fire-retarding only in classes 1–2); slabs over cellars must be fireproof (exceptions for classes 1–2, ceilings above roof spaces, slabs within dwellings — none applies here); solid RC slabs are sufficiently fire-resistant without extra protection under certain conditions.',
         basis=[C['g6_class35'], C['g6_cellar_walls'], C['g6_cellar_slab'], C['g6_slab_except'], C['g6_solid_slab']],
         rubric=['Derives class 3–5 from the 1939 m² (> 400 m²) area via the book\'s gloss', 'Basement walls must be fireproof; slab over the cellar fireproof', 'Judges solid KS masonry and 300 mm RC slab as appropriate (with assumption)', 'Notes no FireRating in the model']),
    dict(project='ac20', derived_from=[], pairing='supplement', question_type='diagnosis',
         question='The external walls of this office building ("Kalksandstein … 300", 54 walls) are modelled as one 300 mm layer of calcium-silicate masonry, plastered on both faces. Judge this single-material external wall against the usual design guidance on external wall construction, and say what a designer would add or change.',
         answer='As modelled, the wall is not a viable heated external wall. It is a single-leaf wall: ArchiCAD reports structure type "Einfach", insulation layer thickness 0.0 and air layer thickness 0.0, and the only material is Kalksandstein 300 mm, plastered both sides. Neufert notes that single-leaf external walls are simple in building-physics terms, but under current thermal insulation requirements they can only be built from materials with high thermal insulation value, such as aerated blocks, with insulating mortars and plasters. Calcium-silicate masonry is a dense, load-bearing unit, the opposite of an insulating block. So either an insulation layer is added (an external insulation system or a cavity/core-insulated two-leaf wall), or the wall is changed to an insulating masonry unit, which would usually need more thickness than 300 mm. At early design stage, this adds roughly 100–200 mm to the wall line all round the 42 × 14 m footprint.',
         evidence=['54 external IfcWall: "Kalksandstein 2816491304 300" (46) and "Kalksandstein 2774059904 300" (8); single IfcMaterial, width 0.30 m.',
                   'ArchiCADProperties: "Struktur - Typ" = Einfach; "Außenseite/Innenseite Oberfläche" = Verputz, weiß; ArchiCADQuantities: Dämmungsschichtdicke 0.0, Luftschichtdicke 0.0.',
                   'Footprint from external walls x 0.00–42.00, y 2.00–14.00 m (with a projecting part to y 16.0).'],
         hidden_knowledge='Single-leaf external walls can only be built with materials of high thermal insulation value (e.g. aerated blocks) and insulating mortars/plasters; single-leaf walls with additional insulation layers are the common alternative.',
         basis=[C['g6_single_leaf']],
         rubric=['Recognises a single-leaf wall with no insulation or air layer', 'States single-leaf walls need high-insulation materials such as aerated blocks', 'Judges dense calcium-silicate masonry unsuitable without insulation', 'Proposes added insulation / two-leaf wall / insulating block']),
    dict(project='fzk_house', derived_from=[], pairing='supplement', question_type='intent',
         question='The FZK house\'s external walls are "Leichtbeton … 300" and its internal walls "Leichtbeton … 240", each a single homogeneous material layer with no insulation layer modelled. Why would a designer choose a single-leaf lightweight-concrete external wall, and why is it thicker than the internal walls?',
         answer='It is a single-leaf external wall. Neufert accepts this form, and it is simple in building-physics terms, but only if the wall material itself insulates well (aerated blocks are his example) and is laid with insulating mortars and plasters. Lightweight concrete (Leichtbeton) is that kind of porous, insulating masonry, so the 300 mm external wall can be both structure and insulation without a separate layer or a second leaf. The extra 60 mm over the 240 mm internal walls is for insulation: the internal walls only have to carry loads and separate rooms, while the external wall also carries the thermal duty, and for a homogeneous wall that means more thickness. This assumes the Leichtbeton is an insulating grade. If it were a dense grade, the wall would need additional insulation like any other single-leaf wall.',
         evidence=['8 IfcWallStandardCase "Leichtbeton 102890359 300" on the perimeter (Wand-Ext-ERDG-1…4, Wand-Ext-OG-1…4), e.g. 3rPX_Juz59peXXY6wDJl18, x 0.00–0.30 m.',
                   '5 IfcWallStandardCase "Leichtbeton 102890359 240" inside (Wand-Int-ERDG-1…5).',
                   'Each a single IfcMaterialLayer (Leichtbeton 102890359, 300 or 240 mm); no insulation layer or covering.'],
         hidden_knowledge='Single-leaf external walls are only viable with materials of high thermal insulation value (e.g. aerated blocks) and insulating mortars/plasters.',
         basis=[C['g6_single_leaf']],
         rubric=['Identifies a single-leaf external wall', 'Links it to the rule that single-leaf walls need high-insulation materials', 'Explains the 300 vs 240 mm difference by the thermal function', 'States the assumption about the lightweight-concrete grade']),
    dict(project='digital_hub', derived_from=[], pairing='supplement', question_type='intent',
         question='Around the building, the model places separate wall elements just outside the structural walls: "WD 200 + Luft 40 + Bekleidung 12" (rock wool, air gap, fibre-cement board) outside the "Leichtbetonmauerwerk 250" façade walls, and "WD hart 200" outside the "STB 300" basement walls and under the basement slab. What construction principle is the designer following, and why is it needed for these particular structural walls?',
         answer='The designer is wrapping the structure in a continuous outer insulation layer, so the structural walls stay on the warm side. Above ground, the 250 mm lightweight-concrete masonry gets 200 mm rock wool, a 40 mm air gap and 12 mm fibre-cement cladding: a back-ventilated façade, with U = 0.151 W/m²K stored on the type. Below ground, the 300 mm reinforced-concrete basement walls and the basement slab get 200 mm hard insulation (perimeter insulation). Neufert gives the reasons. Under current insulation requirements, single-leaf external walls can only be built from materials of high insulation value, which 250 mm masonry alone is unlikely to provide (the model gives no conductivity, so this is an assumption); single-leaf walls with additional insulation layers are therefore the common alternative. And solid concrete walls may be used as external walls only with an additional thermal insulation layer. Putting the insulation outside keeps the mass of the concrete and masonry inside the thermal envelope. It also lets the insulation run unbroken past the slab edges and columns.',
         evidence=['IfcWall "Basiswand:WD 200 + Luft 40 + Bekleidung 12" (4, e.g. 12bPoIwbv0tBGfPfnvCUc2, z 0.00–8.15 m): Faserzementplatte (Equitone natura), Luftschicht, Steinwolle (Rockwool Fixrock033 VS); ThermalTransmittance 0.1508 W/m²K.',
                   'IfcWall "Basiswand:Leichtbetonmauerwerk 250" (10), e.g. 12bPoIwbv0tBGfPfnvCUq4 (y 6.87–7.12 m, E00) directly inside the cladding wall (y 6.62–6.87 m).',
                   'IfcWall "Basiswand:STB 300" basement perimeter (z −3.37…−0.37 m) with "Basiswand:WD hart 200" outside it (e.g. 0CWDnGbzX4Sf1BesL9TjCD, y 26.72–26.92 m); IfcSlab "Geschossdecke:WD 200 hart" under the basement (z −3.87…−3.67 m).'],
         hidden_knowledge='Single-leaf external walls can only be built from high-insulation materials; single-leaf walls with additional insulation layers are the common alternative; solid concrete external walls only with an additional thermal insulation layer.',
         basis=[C['g6_single_leaf'], C['g6_concrete_ext']],
         rubric=['Identifies continuous external insulation (ventilated façade above ground, perimeter insulation below)', 'Cites the rule for concrete external walls', 'Cites the single-leaf masonry rule', 'Explains why insulation sits outside the structure (continuity / thermal mass)']),

    # ============================================================ perimeter ties
    dict(project='fantasy_office_building_3', derived_from=[], pairing='supplement', question_type='compliance',
         question='On OG1, "Corridor west" (≈1.58 m wide, ≈21.3 m long) leads from the individual offices and WCs to the "Staircase core (west)". List the wall types that form its two sides. Assuming the corridor serves as an escape route, what fire performance must those side walls have, and which wall needs the most attention?',
         answer='The side walls of an escape-route corridor must be at least fire-retarding (F 30). The east side is "STB 30.0" reinforced concrete throughout (y −21.10…0.45). The west side is, from south to north: the "STB 25.0" stair-core walls (y −20.80…−13.89), the "STB 20.0" WC wall (y −13.64…−7.84), and then "GK 12.5" between the corridor and Individual offices 1 and 2 (y −7.84…0.50). The concrete walls are non-combustible solid walls, far beyond F 30. The one to watch is the GK 12.5: a 125 mm stud partition of gypsum board with hard insulation between. Non-load-bearing separating walls can be built as stud partitions of various qualities, so it can be detailed to F 30. But it has to be a rated system, and it runs the full storey height (3.70–7.10 m, up to the STB 30.0 slab at 7.10–7.40 m). The model stores no FireRating on any wall. The only rated element on the corridor is the EI 30 door to the WC. There is no glazing in the corridor walls, so no G-glazing sill question arises. (If the whole floor counted as one small use unit, the corridor might be exempt from escape-route rules. The verdict above assumes it is a required corridor.)',
         evidence=['IfcSpace 119 "Corridor west" x −8.93…−7.35, y −20.80…0.48 m (OG1).',
                   'East side: IfcWall 31Jmzg6N54ZQqCBfl7HAUG and …HAEL "Basiswand:STB 30.0" (x −7.35…−7.05).',
                   'West side: …HAPe "STB 25.0" (y −20.80…−13.89), …HAOK "STB 20.0" (y −13.64…−7.84), …HA5K "Basiswand:GK 12.5" (x −9.06…−8.93, y −7.84…0.50, z 3.70–7.10; constituents MW - Gipskarton, Wärmedämmung - Hart, MW - Gipskarton).',
                   'IfcSlab 31Jmzg6N54ZQqCBfl7HAUP "Geschossdecke:STB 30.0" z 7.10–7.40; door 31Jmzg6N54ZQqCBfl7HAOM "…ML - 885X2135 - EI 30" into Toilet men; office doors "Drehflügel 1-flg - Variabel" without rating; no FireRating in Pset_WallCommon.'],
         hidden_knowledge='Corridor walls must be fire-retarding (F 30) as side walls of escape routes; non-load-bearing separating walls can be built as stud partitions of various (fire) qualities.',
         basis=[C['g6_corridor_f30'], C['g6_stud']],
         rubric=['Lists the side walls (STB 30/25/20 and GK 12.5)', 'States F 30 for escape-route corridor walls', 'Flags the GK 12.5 stud partition as needing a rated F 30 system (noting it runs up to the slab)', 'Notes no FireRating in the model / assumption about the corridor status']),
]
